using System;
using UnityEngine;
using UnityEngine.Rendering;
namespace DiwaliGameplay {
public sealed class DiyaRestTarget : MonoBehaviour {
 public Transform rest;public GrabbableItem item;public float radius=1f;
 public Func<bool> isActive;
 Transform ghost;LineRenderer ring;TextMesh message;Material ghostMaterial,lineMaterial;
 Vector3 previousHeldPosition;bool trackedHeld;bool releasedReady;float surfaceOffset;float supportY;
 public bool CanCapture(){return item&&item.WasGrabbed&&!item.IsHeld&&isActive!=null&&isActive()&&(Contains(item,rest,radius)||releasedReady);}
 void Released(UnityEngine.XR.Interaction.Toolkit.SelectExitEventArgs args){if(isActive==null||!isActive())return;if(Contains(item,rest,radius)||trackedHeld&&Crosses(previousHeldPosition,item.transform.position))releasedReady=true;}
 bool Crosses(Vector3 from,Vector3 to){var a=new Vector2(from.x,from.z);var b=new Vector2(to.x,to.z);var target=new Vector2(rest.position.x,rest.position.z);var d=b-a;float t=d.sqrMagnitude>.00001f?Mathf.Clamp01(Vector2.Dot(target-a,d)/d.sqrMagnitude):0;float y=Mathf.Lerp(from.y,to.y,t)-rest.position.y;return (a+d*t-target).sqrMagnitude<=radius*radius&&y>=-1.5f&&y<=2f;}
 public static bool Contains(GrabbableItem item,Transform rest,float radius){if(!item||!rest)return false;var d=item.transform.position-rest.position;return new Vector2(d.x,d.z).sqrMagnitude<=radius*radius&&d.y>=-1.5f&&d.y<=2f;}
 public static DiyaRestTarget Create(Transform parent,Transform rest,GrabbableItem item,float radius,Func<bool> isActive){var go=new GameObject(item.itemId+" ghost target");go.transform.SetParent(parent,false);var target=go.AddComponent<DiyaRestTarget>();target.rest=rest;target.item=item;target.radius=radius;target.isActive=isActive;target.Build();if(item.grab)item.grab.selectExited.AddListener(target.Released);return target;}
 void Build(){surfaceOffset=item.transform.position.y-GameObjectUtility.BoundsOf(item.transform).min.y;var shader=Shader.Find("Universal Render Pipeline/Unlit")??Shader.Find("Sprites/Default");ghostMaterial=new Material(shader);ghostMaterial.SetColor("_BaseColor",new Color(.2f,.9f,1,.2f));ghostMaterial.color=new Color(.2f,.9f,1,.2f);ghostMaterial.SetFloat("_Surface",1);ghostMaterial.SetFloat("_SrcBlend",(float)BlendMode.SrcAlpha);ghostMaterial.SetFloat("_DstBlend",(float)BlendMode.OneMinusSrcAlpha);ghostMaterial.SetFloat("_ZWrite",0);ghostMaterial.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");ghostMaterial.renderQueue=3000;lineMaterial=new Material(shader);lineMaterial.color=new Color(1,.72f,.2f);
 ghost=new GameObject("Matching mesh preview").transform;ghost.SetParent(transform,true);ghost.SetPositionAndRotation(item.transform.position,item.transform.rotation);
 foreach(var source in item.GetComponentsInChildren<MeshFilter>(true)){if(!source.sharedMesh)continue;var go=new GameObject(source.name+" ghost");go.transform.SetPositionAndRotation(source.transform.position,source.transform.rotation);go.transform.localScale=source.transform.lossyScale;go.transform.SetParent(ghost,true);go.AddComponent<MeshFilter>().sharedMesh=source.sharedMesh;var renderer=go.AddComponent<MeshRenderer>();var mats=new Material[source.sharedMesh.subMeshCount];for(int i=0;i<mats.Length;i++)mats[i]=ghostMaterial;var original=source.GetComponent<MeshRenderer>();if(original&&mats.Length==3&&source.name.StartsWith("Sphere"))mats[0]=original.sharedMaterials[0];renderer.sharedMaterials=mats;renderer.shadowCastingMode=ShadowCastingMode.Off;renderer.receiveShadows=false;}
 supportY=rest.position.y-surfaceOffset;float foundSupport=float.NegativeInfinity;foreach(var hit in Physics.RaycastAll(rest.position+Vector3.up*.1f,Vector3.down,2f)){if(hit.collider.transform.IsChildOf(item.transform)||hit.point.y>rest.position.y+.02f)continue;foundSupport=Mathf.Max(foundSupport,hit.point.y);}if(!float.IsNegativeInfinity(foundSupport))supportY=foundSupport;
 var line=new GameObject("Forgiving horizontal drop area");line.transform.SetParent(transform,false);ring=line.AddComponent<LineRenderer>();ring.material=lineMaterial;ring.loop=true;ring.positionCount=48;ring.widthMultiplier=.012f;ring.useWorldSpace=true;
 var label=new GameObject("Placement readiness");label.transform.SetParent(transform,false);message=label.AddComponent<TextMesh>();message.fontSize=44;message.characterSize=.012f;message.anchor=TextAnchor.MiddleCenter;message.alignment=TextAlignment.Center;}
 void LateUpdate(){if(!rest||!item)return;if(item.IsHeld){if(!trackedHeld)previousHeldPosition=item.transform.position;trackedHeld=true;releasedReady=false;}else if(trackedHeld){if(isActive!=null&&isActive()&&Crosses(previousHeldPosition,item.transform.position))releasedReady=true;trackedHeld=false;}bool active=isActive!=null&&isActive();ghost.gameObject.SetActive(active);ring.enabled=active;message.gameObject.SetActive(active);if(!active){releasedReady=false;if(item.IsHeld)previousHeldPosition=item.transform.position;return;}ghost.SetPositionAndRotation(rest.position,rest.rotation);bool ready=item.WasGrabbed&&Contains(item,rest,radius);var color=ready?new Color(.25f,1,.55f):new Color(1,.72f,.2f);ring.startColor=ring.endColor=color;lineMaterial.color=color;ghostMaterial.SetColor("_BaseColor",new Color(color.r,color.g,color.b,.22f));for(int i=0;i<48;i++){float a=i*Mathf.PI*2/48;ring.SetPosition(i,new Vector3(rest.position.x+Mathf.Cos(a)*Mathf.Min(radius,.28f),supportY+.018f,rest.position.z+Mathf.Sin(a)*Mathf.Min(radius,.28f)));}message.text=ready?"READY\nRelease to place":"PLACE HERE";message.color=color;message.transform.position=rest.position+Vector3.up*.2f;var camera=Camera.main;if(camera)message.transform.rotation=Quaternion.LookRotation(message.transform.position-camera.transform.position,camera.transform.up);if(item.IsHeld)previousHeldPosition=item.transform.position;}
 void OnDestroy(){if(item&&item.grab)item.grab.selectExited.RemoveListener(Released);if(ghostMaterial)Destroy(ghostMaterial);if(lineMaterial)Destroy(lineMaterial);}
}
}
